// Real nickname lookup needs a live call to the game's official/third-party
// "check role" endpoint through a backend (can't be faked reliably offline).
// This preview only validates the ID's format so it never shows a wrong name.
function verifyGameIdFormat(gameId) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (!gameId || gameId.length < 6 || !/^\d+$/.test(gameId)) {
        reject(new Error("Game ID ပုံစံ မှားနေပါသည်"));
      } else {
        resolve(true);
      }
    }, 700);
  });
}

// Telegram usernames: 5-32 chars, letters/digits/underscores, must start
// with a letter (Telegram's own username rules). The leading "@" (if the
// customer types it) is stripped before this check runs.
function verifyTelegramUsernameFormat(username) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (!username || !/^[A-Za-z][A-Za-z0-9_]{4,31}$/.test(username)) {
        reject(new Error("Telegram username ပုံစံ မှားနေပါသည်"));
      } else {
        resolve(true);
      }
    }, 700);
  });
}

function fmt(n) {
  return (n ?? 0).toLocaleString("en-US");
}

// Applies a reseller's flat discount to a price, rounding to the nearest
// whole unit (MMK/THB don't use decimals here). `percent` is 0 for regular
// users, so this is a no-op unless the logged-in user is a reseller.
// If `pkg` carries a `resellerPrice` override for the given `currency`
// (used for e.g. ML's Weekly Pass, which has a fixed reseller price
// instead of a percentage discount), that overrides the percent math —
// every other item is unaffected.
function applyResellerDiscount(price, percent, pkg, currency) {
  if (!percent) return price;
  const override = pkg && pkg.resellerPrice && pkg.resellerPrice[currency];
  if (override != null) return override[0];
  return Math.round(price * (1 - percent / 100));
}

// Clipboard helper with a manual-copy fallback for sandboxed environments
// where navigator.clipboard may be blocked.
function copyText(text, onDone) {
  const fallback = () => {
    try {
      const ta = document.createElement("textarea");
      ta.value = text;
      ta.style.position = "fixed";
      ta.style.opacity = "0";
      document.body.appendChild(ta);
      ta.focus();
      ta.select();
      document.execCommand("copy");
      document.body.removeChild(ta);
      onDone(true);
    } catch (e) {
      onDone(false);
    }
  };
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(() => onDone(true)).catch(fallback);
  } else {
    fallback();
  }
}

