const REGION_PREFIX_RE = /^(Global|PH|SEA|LATAM|RU|Thailand)\s+/;
const BONUS_SUFFIX_RE = /\s*\([^)]*Bonus\)\s*$/i;

/** Strips the region prefix and "(First Top-Up Bonus)" suffix for display only — the underlying `label` (used for orders) is untouched. */
function displayLabel(rawLabel) {
  return rawLabel.replace(REGION_PREFIX_RE, "").replace(BONUS_SUFFIX_RE, "").trim();
}

function isBonusLabel(rawLabel) {
  return BONUS_SUFFIX_RE.test(rawLabel);
}

/** Racing Master items whose (region-stripped) label ends in "Gems" are pure currency; everything else (Novice Pack, Weekly/Monthly Card, MP tiers, Growth Fund, etc.) is a pass/bundle. */
function isGemsLabel(rawLabel) {
  return /Gems$/i.test(displayLabel(rawLabel));
}

function PkgSection({ num, title, items, currency, discountPercent = 0, onPick }) {
  const currencyLabel = currency === "mmk" ? "ကျပ်" : "ဘတ်";
  return (
    <div>
      <div className="flex items-center gap-2 mb-2">
        <span className="w-6 h-6 rounded-full bg-emerald-500 text-white text-xs font-bold flex items-center justify-center">{num}</span>
        <span className="text-white font-bold drop-shadow">{title}</span>
      </div>
      <div className="grid grid-cols-3 gap-2">
        {items.map((it) => {
          const rawPrice = it[currency][0];
          const priceVal = applyResellerDiscount(rawPrice, discountPercent, it, currency);
          const rawLabel = it.label || it.name;
          const label = displayLabel(rawLabel);
          const showBonusBadge = isBonusLabel(rawLabel);
          return (
            <button key={it.id} onClick={() => onPick(it)} className="relative bg-white rounded-lg overflow-hidden text-center shadow active:scale-95 transition">
              {showBonusBadge && (
                <span className="absolute top-1 right-1 z-10 bg-[#c05b58] text-white text-[10px] font-bold px-1.5 py-0.5 rounded-full shadow">2X</span>
              )}
              {it.image ? (
                <img
                  src={it.image}
                  alt={label}
                  className={`w-full h-20 ${it.imgFit === "contain" ? "object-contain bg-[#0a0a0a] p-1" : "object-cover"}`}
                />
              ) : (
                <div className="h-20 bg-slate-100" />
              )}
              <div className="p-2">
                <div className="text-[11px] font-bold leading-tight mb-1">{label}</div>
                {priceVal < rawPrice && (
                  <div className="text-[10px] text-rose-500 line-through leading-none">{fmt(rawPrice)} {currencyLabel}</div>
                )}
                <div className="text-sm font-bold text-amber-500">{fmt(priceVal)} {currencyLabel}</div>
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
}

// TikTok / Facebook packages: shows the platform logo, the original price
// TikTok / Facebook packages: shows the platform logo and a single plain
// price (no strikethrough / no discount display).
function SocialPkgGrid({ items, currency, logo, discountPercent = 0, onPick }) {
  const currencyLabel = currency === "mmk" ? "ကျပ်" : "ဘတ်";
  return (
    <div className="grid grid-cols-3 gap-2">
      {items.map((it) => {
        const [rawPrice] = it[currency];
        const price = applyResellerDiscount(rawPrice, discountPercent, it, currency);
        return (
          <button key={it.id} onClick={() => onPick(it)} className="bg-white rounded-lg overflow-hidden text-center shadow active:scale-95 transition p-2">
            <img src={logo} alt="" className="w-9 h-9 object-contain mx-auto mb-1" />
            <div className="text-[11px] font-bold leading-tight mb-1 line-clamp-2">{it.label}</div>
            <div className="text-sm font-bold text-slate-900">{fmt(price)} {currencyLabel}</div>
          </button>
        );
      })}
    </div>
  );
}
